namespace Rentals.Domain.Applications;

/// <summary>A residence as entered. Values may be missing or invalid while the section is a draft.</summary>
public sealed record ResidenceData(
    Guid Id,
    string? Address,
    string? LandlordName,
    string? LandlordPhone,
    DateOnly? MoveInDate,
    DateOnly? MoveOutDate);

/// <summary>A prior residence. The id is generated by the client so a list can be edited offline.</summary>
public class Residence
{
    private Residence() { }

    public Guid Id { get; private set; }

    public Guid ApplicationId { get; private set; }

    public string? Address { get; private set; }

    public string? LandlordName { get; private set; }

    public string? LandlordPhone { get; private set; }

    public DateOnly? MoveInDate { get; private set; }

    public DateOnly? MoveOutDate { get; private set; }

    internal static Residence Create(Guid applicationId, ResidenceData data)
    {
        var residence = new Residence { Id = data.Id, ApplicationId = applicationId };
        residence.Update(data);
        return residence;
    }

    internal void Update(ResidenceData data)
    {
        Address = Text.Clean(data.Address);
        LandlordName = Text.Clean(data.LandlordName);
        LandlordPhone = Text.Clean(data.LandlordPhone);
        MoveInDate = data.MoveInDate;
        MoveOutDate = data.MoveOutDate;
    }
}
